-- ---------------- checks (should read: expenses 74121.62, funding 72942.00, revenue 4640.00) ----------------
SELECT c.code, c.name, count(*) AS rows, sum(e.amount) AS total
FROM expenses e JOIN expense_categories c ON c.id = e.category_id
WHERE e.source = 'import_xlsx' GROUP BY c.code, c.name ORDER BY c.code;
SELECT (SELECT sum(amount) FROM expenses WHERE source = 'import_xlsx') AS imported_total,
       74121.62 AS expected_total,
       (SELECT sum(amount) FROM finance_funding WHERE source = 'import_xlsx') AS funding_total,
       (SELECT sum(amount) FROM finance_revenues WHERE source = 'import_xlsx') AS revenue_total,
       (SELECT count(*) FROM expenses WHERE source = 'import_xlsx') AS expense_rows,
       (SELECT count(*) FROM expense_versions v JOIN expenses e ON e.id = v.expense_id WHERE e.source = 'import_xlsx') AS versions,
       (SELECT count(*) FROM expenses WHERE source = 'import_xlsx' AND breakdown IS NOT NULL) AS itemised_rows;
